    categories:["Vladimir Kachalov","Soviet generals","Twenty-Eighth Army","Battle of Roslavl","Order No. 270"],facts:[["Born","27 July 1890 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Birthplace","Gorodishche · Saratov Governorate <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Service","Imperial Russian Army · Red Army <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Rank","Lieutenant general <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Final command","Twenty-Eighth Army <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Divergence boundary","1 August 1941 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Killed","Starinka · 4 August 1941 <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Condemned in absentia","Order No. 270 · 16 August 1941 <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Later official status","Open <sup class='canon-note' data-provenance='e'>[e]</sup>"]]
